import sys

def main():
    input = sys.stdin.read
    data = input().splitlines()

    n, q = map(int, data[0].split())
    head_moves = [(1, 0)]

    results = []

    for line in data[1:]:
        parts = line.split()
        if parts[0] == '1':
            direction = parts[1]
            last_x, last_y = head_moves[-1]
            if direction == 'R':
                new_x, new_y = last_x + 1, last_y
            elif direction == 'L':
                new_x, new_y = last_x - 1, last_y
            elif direction == 'U':
                new_x, new_y = last_x, last_y + 1
            elif direction == 'D':
                new_x, new_y = last_x, last_y - 1
            head_moves.append((new_x, new_y))
        else:
            p = int(parts[1])
            m = len(head_moves) - 1
            if m >= p - 1:
                x, y = head_moves[m - (p - 1)]
            else:
                x = p - m
                y = 0
            results.append(f"{x} {y}")

    print("\n".join(results))

if __name__ == "__main__":
    main()
